describe('Search Results Update with Debounce', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should debounce search results and update as user types', () => {
    // Setup: intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('');
    }).as('searchRequest');

    // Verify initial state
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-results"]').should('contain', 'No results found');

    // Type a query
    cy.get('[data-testid="search-input"]').type('test');

    // Wait for debounce timeout
    cy.wait('@searchRequest', { timeout: 350 });

    // Verify results are updated
    cy.get('[data-testid="search-results"]').should('contain', 'Test');

    // Type more characters
    cy.get('[data-testid="search-input"]').type('testuser');

    // Wait for debounce timeout
    cy.wait('@searchRequest', { timeout: 350 });

    // Verify results are updated with full query
    cy.get('[data-testid="search-results"]').should('contain', 'Test user');

    // Verify no results are shown for empty input
    cy.get('[data-testid="search-input"]').clear().type('');
    cy.wait('@searchRequest', { timeout: 350 });
    cy.get('[data-testid="search-results"]').should('contain', 'No results found');
  });

  it('should handle edge case: debounce timeout with no results', () => {
    // Setup: intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('');
    }).as('searchRequest');

    // Verify initial state
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-results"]').should('contain', 'No results found');

    // Type a query that should not return results
    cy.get('[data-testid="search-input"]').type('nonexistentuser');

    // Wait for debounce timeout
    cy.wait('@searchRequest', { timeout: 350 });

    // Verify results are still empty
    cy.get('[data-testid="search-results"]').should('contain', 'No results found');

    // Verify debounce works even with no results
    cy.get('[data-testid="search-input"]').clear().type('test');
    cy.wait('@searchRequest', { timeout: 350 });
    cy.get('[data-testid="search-results"]').should('contain', 'Test');
  });
});
